library(ggplot2);library(systemfonts)
register_font('Manrope',plain='assets/Manrope-Regular.ttf',bold='assets/Manrope-Bold.ttf')
d<-read.csv('data/anambra_2021_2022_original_slide.csv');d$group<-ifelse(rank(-d$annual_catch,ties.method='first')<=3,'Three highest-catch sites','Other sites');share<-sum(sort(d$annual_catch,decreasing=TRUE)[1:3])/sum(d$annual_catch);cat('sites',nrow(d),'positive',sum(d$annual_catch>0),'flies',sum(d$annual_catch),'top3 share',share,'\n')
p<-ggplot(d,aes(site_index,annual_catch,fill=group))+geom_col(width=.78)+scale_fill_manual(values=c('Three highest-catch sites'='#F07F3C','Other sites'='#00ACA9'),guide='none')+scale_x_continuous(breaks=c(1,10,20,30,40,50,58))+scale_y_continuous(labels=scales::label_comma(),expand=expansion(mult=c(0,.08)))+annotate('text',x=32,y=5700,label='58 sites sampled for a year\n3 sites supplied 92% of flies',hjust=0,size=7.2,family='Manrope',colour='#1B1B1B',lineheight=1.25)+labs(x='Collection sites',y='Annual fly catch')+theme_minimal(base_size=22,base_family='Manrope')+theme(panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),panel.grid.major.y=element_line(colour='#E8EEEB'),axis.text=element_text(colour='#58595B',size=18),plot.background=element_rect(fill='#FAFAFA',colour=NA),plot.margin=margin(15,25,15,15))
for(ext in c('svg','png','pdf'))ggsave(paste0('assets/anambra-case.',ext),p,width=12,height=4.8,dpi=300,bg='#FAFAFA',device=if(ext=='pdf')cairo_pdf else if(ext=='svg')svglite::svglite else 'png')
system2('python3','embed_svg_fonts.py')
